-- the delete below checks food_entries' foreign key once per row: indexed, not a sequential scan each (055 creates this
-- index; created here too for a database that predates that)
CREATE INDEX IF NOT EXISTS food_entries_food_item_idx ON public.food_entries (food_item_id) WHERE food_item_id IS NOT NULL;

CREATE TEMP TABLE _fp055d ON COMMIT DROP AS SELECT
  (SELECT count(*) || ':' || md5(coalesce(string_agg(concat_ws(':', id, food_item_id, quantity_g, calories, protein_g, carbs_g, fat_g, fiber_g), ',' ORDER BY id), ''))
     FROM public.food_entries) AS e,
